(72, 'exec', 'const patch = "*** Begin Patch\n*** Update File: /work/semantic.k\n@@\n-requires \"verification-interface.k\"\n-\n module MPY-SYNTAX\n*** Delete File: /work/verification-interface.k\n*** Add File: /work/verification.k\n+requires \"semantic.k\"\n+\n+module VERIFICATION\n+  imports SEMANTIC\n+\n+  // The postcondition names the independently visible mathematical result.\n+  // pyEval is the precedence evaluator defined by the semantics; expected is\n+  // deliberately kept in the verification layer so specifications never\n+  // mention an implementation cell or continuation.\n+  syntax Int ::= expected ( Ops , Ints ) [function]\n+  rule expected(OS, IS) => pyEval(OS, IS)\n+\n+  syntax Bool ::= validOps ( Ops ) [function, total]\n+  rule validOps(.Ops) => true\n+  rule validOps(Op(O, OS)) => validOperator(O) andBool validOps(OS)\n+\n+  syntax Bool ::= validOperator ( String ) [function, total]\n+  rule validOperator(\"+\") => true\n+  rule validOperator(\"-\") => true\n+  rule validOperator(\"*\") => true\n+  rule validOperator(\"//\") => true\n+  rule validOperator(\"**\") => true\n+  rule validOperator(O) => false\n+    requires O =/=String \"+\"\n+     andBool O =/=String \"-\"\n+     andBool O =/=String \"*\"\n+     andBool O =/=String \"//\"\n+     andBool O =/=String \"**\"\n+\n+  syntax Bool ::= nonNegative ( Ints ) [function, total]\n+  rule nonNegative(.Ints) => true\n+  rule nonNegative(Num(I, IS))\n+    => (I >=Int 0) andBool nonNegative(IS)\n+endmodule\n*** Add File: /work/spec.k\n+requires \"verification.k\"\n+\n+module SPEC\n+  imports VERIFICATION\n+\n+  // Universal source-level theorem.  Under the prompt's shape and value\n+  // preconditions, executing the exact translated function reaches the\n+  // precedence-defined mathematical result.\n+  claim\n+    <k>\n+      Module(\n+        FuncDef(\"do_algebra\", Params(\"operator\", \"operand\"),\n+          Assign(\n+            Name(\"expression\"),\n+            Call(Name(\"str\"), Subscript(Name(\"operand\"), Int(0))))\n+          For(TupleExpr(Name(\"oprt\"), Name(\"oprn\")), Call(\n+            Name(\"zip\"),\n+            Name(\"operator\"),\n+            Subscript(Name(\"operand\"), Slice(Int(1), NoBound, NoBound))),\n+            AugAssign(\n+              Name(\"expression\"),\n+              \"+\",\n+              BinOp(\"+\", Name(\"oprt\"),\n+                    Call(Name(\"str\"), Name(\"oprn\")))))\n+          Return(Call(Name(\"eval\"), Name(\"expression\")))))\n+      ~> invoke\n+      => answer(expected(OS, Num(FIRST, REST))) ...\n+    </k>\n+    <operators> ops(OS) </operators>\n+    <operands> ints(Num(FIRST, REST)) </operands>\n+    <expression>\n+      noText => builder(OS, Num(FIRST, REST), .Ops, .Ints)\n+    </expression>\n+    requires aligned(OS, REST)\n+     andBool validOps(OS)\n+     andBool nonNegative(Num(FIRST, REST))\n+\n+  // Prompt example: multiplication binds tighter than addition/subtraction.\n+  claim expected(\n+          Op(\"+\", Op(\"*\", Op(\"-\", .Ops))),\n+          Num(2, Num(3, Num(4, Num(5, .Ints)))))\n+        => 9\n+\n+  // Exponentiation is right associative: 2 ** (3 ** 2), not (2 ** 3) ** 2.\n+  claim expected(\n+          Op(\"**\", Op(\"**\", .Ops)),\n+          Num(2, Num(3, Num(2, .Ints))))\n+        => 512\n+\n+  // Floor division is in the multiplicative precedence group.\n+  claim expected(\n+          Op(\"//\", Op(\"+\", .Ops)),\n+          Num(7, Num(3, Num(2, .Ints))))\n+        => 4\n+\n+  // Addition is performed after the following multiplication: 2 + 3 * 4.\n+  claim expected(\n+          Op(\"+\", Op(\"*\", .Ops)),\n+          Num(2, Num(3, Num(4, .Ints))))\n+        => 14\n+\n+  // Subtraction is left associative: (10 - 3) - 2.\n+  claim expected(\n+          Op(\"-\", Op(\"-\", .Ops)),\n+          Num(10, Num(3, Num(2, .Ints))))\n+        => 5\n+endmodule\n*** End Patch";
